def arrow(): return '<span aria-hidden="true">↗</span>'
def btn(text,href,cls='primary'): return f'<a class="button {cls}" href="{href}">{text} {arrow()}</a>'
def pack(b,extra=''):
 return f'''<div class="pack {extra}" aria-label="Illustrated {b['name']} packaging concept"><div class="pack-seal"></div><img class="pack-logo" src="/assets/ploomi-stacked.svg" width="1360" height="868" alt="Ploomi Coffee by Bermito"><img class="pack-art" src="/assets/{b['art']}" alt="" loading="lazy"><div class="pack-label"><span>COFFEE FOR YOUR BUSINESS</span><strong>{b['name']}</strong><small>ILLUSTRATIVE PACKAGING · 1 KG</small></div></div>'''
def card(b):
 return f'''<article class="coffee-card"><a class="coffee-image {b['cls']}" href="/coffees/{b['id']}/" aria-label="Explore {b['name']}"><span class="tiny-label">BLEND IDEA / {b['number']}</span>{pack(b)}<span class="circle-link" aria-hidden="true">↗</span></a><div class="coffee-caption"><h3><a href="/coffees/{b['id']}/">{b['name']}</a></h3><p>{b['tag']}</p><span class="small-note">{b['note']}</span></div></article>'''
def header(active):
 return f'''<a class="skip" href="#main">Skip to content</a><div class="announcement">Specialty coffee for businesses, by Bermito. <span>Free wholesale delivery across Kerala <span aria-hidden="true">↗</span></span></div><header class="site-header"><a class="brand" href="/" aria-label="Ploomi Coffee home"><img src="/assets/ploomi-horizontal.svg" alt="Ploomi Coffee by Bermito" width="2822" height="765"></a><nav aria-label="Main navigation" id="main-nav"><a {'aria-current="page"' if active=='coffees' else ''} href="/coffees/">Our coffees</a><a {'aria-current="page"' if active=='wholesale' else ''} href="/wholesale/">For your business</a><a {'aria-current="page"' if active=='about' else ''} href="/about/">Our story</a><a {'aria-current="page"' if active=='contact' else ''} href="/contact/">Let’s talk</a><a class="menu-samples" href="/samples/">Request paid samples</a></nav><a class="button primary header-cta" href="/samples/">Try our coffee <span aria-hidden="true">↗</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Open menu"><span></span><span></span></button></header>'''
def cta():
 return f'''<section class="cta section"><div><p class="eyebrow">COFFEE FOR YOUR CAFÉ OR BUSINESS</p><h2>Let’s find the coffee<br><em>that fits your menu.</em></h2></div><div><p>Tell us what you serve, how much coffee you need and how you brew. We’ll discuss suitable coffees, paid samples and a quote.</p>{btn('Start a conversation','/contact/','white')}</div></section>'''
def footer():
 return f'''<footer><div class="footer-top"><a href="/"><img src="/assets/ploomi-stacked.svg" alt="Ploomi Coffee by Bermito" width="1360" height="868" loading="lazy"></a><p>Specialty coffee by Bermito.<br>Roasted in Kozhikode, for businesses across Kerala.</p><div><a href="/coffees/">Our coffees</a><a href="/wholesale/">For your business</a><a href="/samples/">Request samples</a></div><div><a href="/about/">Our story</a><a href="/contact/">Let’s talk</a><a href="/faq/">Questions, answered</a></div><div><a href="mailto:{EMAIL}">{EMAIL}</a><a href="https://wa.me/{PHONE}" target="_blank" rel="noopener">WhatsApp ↗</a><a href="https://www.instagram.com/bermitoindia/" target="_blank" rel="noopener">Bermito on Instagram ↗</a></div></div><div class="footer-bottom"><span>© 2026 Ploomi Coffee · by Bermito Coffee Labs LLP</span><a href="/privacy/">Privacy & enquiries</a><a href="https://bermito.com/" target="_blank" rel="noopener">Meet Bermito ↗</a></div></footer>'''
def page(path,title,desc,body,active='',extra=''):
 p=D/path.strip('/')/'index.html' if path else D/'index.html';p.parent.mkdir(parents=True,exist_ok=True)
 canonical=ORIGIN+('/'+path.strip('/')+'/' if path else '/')
 data={'@context':'https://schema.org','@type':'Organization','name':'Ploomi Coffee by Bermito','url':ORIGIN,'logo':ORIGIN+'/assets/ploomi-stacked.svg','email':EMAIL,'telephone':'+91 98475 99828','areaServed':'Kerala, India','parentOrganization':{'@type':'Organization','name':'Bermito Coffee Roasters','url':'https://bermito.com/'}}
 p.write_text(f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | Ploomi Coffee by Bermito</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="theme-color" content="#0A2F9A"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{html.escape(title,quote=True)} · Ploomi Coffee"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{ORIGIN}/assets/house.webp"><link rel="icon" href="/favicon.ico?v=20261115" sizes="16x16 32x32 48x48"><link rel="icon" href="/assets/ploomi-two-o.svg" type="image/svg+xml" sizes="any"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png" sizes="180x180"><link rel="stylesheet" href="/styles.css?v=approved-logos-1"><script type="application/ld+json">{json.dumps(data)}</script><script src="/app.js" defer></script></head><body>{header(active)}<main id="main">{body}</main>{footer()}{extra}</body></html>''')
steps='''<div class="steps"><article><span>01 /</span><h3>Tell us about<br>your place.</h3><p>Share your menu, brewing equipment and the amount of coffee you expect to use. If you are still planning, an estimate is enough.</p></article><article><span>02 /</span><h3>Let’s find<br>your coffee.</h3><p>Choose a direction or ask for a recommendation. We’ll confirm sample availability, pricing and delivery charges before payment.</p></article><article><span>03 /</span><h3>Make it<br>your everyday.</h3><p>After you have explored the options, we’ll discuss your quote, order quantity and payment terms. Wholesale delivery is free across Kerala.</p></article></div>'''
faqitems=[('Is there a minimum wholesale order?','No. There is no minimum order quantity for wholesale coffee. Tell us what you need and we’ll prepare a quotation.'),('Where do you deliver?','We supply across Kerala. Wholesale delivery within Kerala is free. Paid samples have separate delivery charges, which we’ll confirm before sending them.'),('How much does the coffee cost?','Wholesale pricing is quoted after we understand your coffee preferences, quantity and business needs. Payment terms are discussed directly.'),('Can I try samples first?','Yes. Samples are paid, and delivery charges apply. You can choose your preferred direction or ask for recommendations. We’ll confirm availability, sample cost and delivery before you pay.'),('Are the blends on this website available now?','Tiramisu Blend, House Blend and Christmas Blend are illustrative concepts for our developing range. Their packaging, profiles and availability are not final. Get in touch to discuss current sampling options.'),('Can you make a blend for my café?','We welcome custom-blend enquiries. Tell us about your menu, brewing setup and flavour preferences so we can discuss what is possible.'),('Can I order and pay through the website?','For now, all orders begin with an enquiry by WhatsApp or email. We confirm the coffee, quotation, delivery and payment terms directly.'),('Do you offer private labelling?','No. Private labelling is not part of our current offering. We can discuss Ploomi wholesale supply and custom blends for your café.')]
def faqs(items): return '<div class="faqs">'+''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><p>{a}</p></details>' for q,a in items)+'</div>'
home=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow">SPECIALTY COFFEE FOR CAFÉS & BUSINESSES</p><h1>Coffee for the cups<br><em>you serve every day.</em></h1><p class="hero-desc">From a busy café’s morning espresso to the coffee served at your office, the right choice depends on how you brew and who you serve. Ploomi brings Bermito’s approach to roasting to businesses across Kerala.</p><div class="actions">{btn('Find your coffee','/coffees/')}{btn('Let’s talk business','/wholesale/','text')}</div><div class="hero-foot"><span class="little-star" aria-hidden="true">✳</span><span>Roasted in Kozhikode.<br>Made for places across Kerala.</span></div></div><div class="hero-art"><span class="hand-note">for cafés,<br>and the cups that matter.</span><img src="/assets/house.webp" alt="Loose hand-drawn illustration of a blue neighbourhood coffee shop" fetchpriority="high"><div class="round-stamp"><span>BY BERMITO</span><b>From our<br>place to yours.</b><span>KOZHIKODE, KERALA</span></div></div></section><div class="ribbon" aria-label="Coffee for cafés, bakeries, restaurants, hotels and offices"><div>CAFÉS <i>✳</i> BAKERIES <i>✳</i> RESTAURANTS <i>✳</i> HOTELS <i>✳</i> OFFICES <i>✳</i> YOUR NEXT IDEA <i>✳</i><span aria-hidden="true"> CAFÉS <i>✳</i> BAKERIES <i>✳</i> RESTAURANTS <i>✳</i> HOTELS <i>✳</i> OFFICES <i>✳</i> YOUR NEXT IDEA <i>✳</i></span></div></div><section class="section coffees-section"><div class="section-heading"><div><p class="eyebrow">THREE BLEND CONCEPTS</p><h2>A first look at<br><em>the Ploomi range.</em></h2></div><div><p>Three ideas for coffees we’re developing: an everyday house coffee, a dessert-inspired blend and a seasonal release.</p><a class="text-link" href="/coffees/">Explore the blends ↗</a></div></div><div class="coffee-grid">{''.join(card(b) for b in blends)}</div><p class="concept-note">These blends and packs are concepts. Coffee components, roast profiles, tasting notes, sizes and availability will be confirmed as the range develops.</p></section><section class="business-section section"><div class="business-intro"><p class="eyebrow">WHAT PLOOMI CAN HELP WITH</p><h2>Coffee for your menu.<br><em>Support for your team.</em></h2><p>Choosing coffee is only the beginning. We can discuss your menu, your equipment and how your team brews, then plan coffee supply around your needs.</p>{btn('Coffee for your business','/wholesale/','outline')}</div><div class="service-list"><a href="/wholesale/#supply"><span>01</span><div><h3>Wholesale coffee supply.</h3><p>Order the quantity your business needs, with no minimum wholesale order. We’ll quote after discussing your requirements; wholesale delivery is free across Kerala.</p></div><b>↗</b></a><a href="/wholesale/#custom"><span>02</span><div><h3>Custom blend enquiries.</h3><p>Looking for a coffee to call your house blend? Tell us how it will be served, your preferred flavour direction and the equipment you use.</p></div><b>↗</b></a><a href="/wholesale/#support"><span>03</span><div><h3>Brewing and café support.</h3><p>Ask us about barista training, brewing guidance and choosing equipment for a new or existing café.</p></div><b>↗</b></a></div></section><section class="section story-strip"><div class="story-photo"><img src="/assets/farm.jpg" alt="Coffee drying beds in Sri Lanka, from Bermito’s Kothmale origin imagery" loading="lazy"><span>THE PEOPLE. THE PROCESS. THE CUP.</span></div><div><p class="eyebrow">A NEW CHAPTER, BY BERMITO</p><h2>From Bermito’s roastery<br><em>to your coffee bar.</em></h2><p>Bermito began with a small lot of coffee that made us curious about why one cup can taste so different from another. That question became a roastery in Kozhikode.</p><p>At Bermito, we roast in small batches, adjusting heat, airflow and time for each coffee. Ploomi brings that attention to cafés and businesses, with space to discuss the coffee that fits the way you serve it.</p><a class="text-link" href="/about/">Get to know us ↗</a></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">HOW A WHOLESALE ENQUIRY WORKS</p><h2>From your first enquiry<br><em>to your first order.</em></h2></div>{btn('Request paid samples','/samples/','outline')}</div>{steps}</section><section class="section faq-section"><div><p class="eyebrow">A FEW GOOD QUESTIONS</p><h2>Wholesale coffee,<br><em>answered.</em></h2><a class="text-link" href="/faq/">All the answers ↗</a></div>{faqs(faqitems[:4])}</section>{cta()}'''
page('','Coffee for cafés & good company','Ploomi Coffee by Bermito. Wholesale coffee, custom blends and café support across Kerala. No minimum wholesale order. Request paid samples or a quote.',home)
page('coffees','Our coffee concepts','Explore the Tiramisu, House and Christmas blend concepts from Ploomi Coffee by Bermito. Talk to us about coffee for your café.',f'''<section class="page-intro section"><p class="eyebrow">THE PLOOMI COFFEE FAMILY</p><h1>Coffees made for<br><em>the way you serve.</em></h1><p>A coffee served as espresso has a different job from one poured into a large iced latte. These three blend concepts are a starting point for discussing the menu and flavours you have in mind.</p></section><section class="section range"><div class="range-head"><span>THE FIRST THREE / CONCEPT COLLECTION</span><a href="/samples/">Help me choose ↗</a></div><div class="coffee-grid">{''.join(card(b) for b in blends)}</div><div class="notice"><b>Our range is still being developed.</b><p>These are illustrative blends, not final product specifications. Origins, tasting notes, roast profiles, packaging sizes and availability will be confirmed before any order.</p></div></section><section class="section split callout"><h2>Your café.<br><em>Your own direction.</em></h2><div><p>Looking for something specific? Tell us whether your menu is mostly milk drinks, black coffee or filter, and what kind of flavour you’d like to serve. We can discuss a custom blend for your business.</p>{btn('Tell us your idea','/contact/?interest=Custom%20blend')}</div></section>{cta()}''','coffees')
for b in blends:
 body=f'''<div class="breadcrumb"><a href="/coffees/">Our coffees</a><span>/</span>{b['name']}</div><section class="product-hero"><div class="product-visual {b['cls']}">{pack(b)}<span class="tiny-label">ILLUSTRATIVE PACKAGING · CONCEPT {b['number']}</span></div><div class="product-info"><p class="eyebrow">PLOOMI / {b['note'].upper()}</p><h1>{b['name'].replace(' Blend','<br><em>Blend.</em>')}</h1><p class="lead">{b['tag']}</p><p>{b['desc']}</p><ul class="product-points">{''.join('<li>'+s+'</li>' for s in b['ideas'])}</ul><div class="notice small"><b>This is a concept blend.</b><p>Final coffee, flavour notes, roast profile and availability are still to be confirmed. Packaging is illustrative.</p></div><div class="actions">{btn('Ask about this blend','/contact/?interest='+b['name'].replace(' ','%20'))}{btn('Explore paid samples','/samples/?blend='+b['id'],'outline')}</div><p class="fine">Wholesale: no minimum order · Quoted to your requirements<br>Free wholesale delivery across Kerala</p></div></section><section class="section split"><div><p class="eyebrow">LET’S FIND THE RIGHT FIT</p><h2>A better choice starts<br><em>with your menu.</em></h2></div><div><p>Tell us which drinks make up your menu, the equipment you use and whether you prefer a familiar or more expressive cup. We can discuss a suitable coffee direction and the quantity your business needs.</p><p>Paid samples can help you explore the options. Availability, sample cost and delivery charges are confirmed before payment.</p><a class="text-link" href="/wholesale/">How we work together ↗</a></div></section><section class="section"><div class="section-heading"><h2>Explore another<br><em>blend concept.</em></h2><a class="text-link" href="/coffees/">All blends ↗</a></div><div class="coffee-grid two">{''.join(card(x) for x in blends if x!=b)}</div></section>{cta()}'''
 page('coffees/'+b['id'],b['name']+' — concept',b['desc'],body,'coffees')
services=[('supply','01','Coffee for the way<br>you serve.','Wholesale supply','Whether you need coffee for espresso, milk drinks or a filter bar, tell us about your menu and expected usage. We’ll discuss the options and prepare a quote. There is no minimum wholesale order, and wholesale delivery across Kerala is free.',['Pricing by quotation','Free wholesale delivery across Kerala','Payment and supply schedule discussed directly']),('custom','02','A house blend<br>for your café.','Custom blends','A blend can be developed around the drinks you serve most. We start with your preferred flavour direction, equipment and menu, then discuss sampling, development and pricing with you.',['Share your preferred flavour direction','Discuss brewing method and menu','Sampling and development agreed together']),('support','03','From the grinder<br>to the cup.','Training & brewing support','Coffee preparation changes what reaches the table. Ask us about espresso dial-in, brewing guidance and barista training for your team; we’ll discuss the support you need and its scope.',['Barista training enquiries','Brewing and menu guidance','Equipment advice']),('new-cafe','04','Opening a café?<br>Start with the menu.','New café guidance','If you are planning a café, we can discuss the coffee you want to serve, suitable brewing equipment and how the drinks fit your menu. Guidance and pricing are discussed according to your requirements.',['Coffee and equipment guidance','Menu planning conversations','Support scope and pricing confirmed with you'])]
wholesale=f'''<section class="page-intro section"><p class="eyebrow">COFFEE FOR YOUR BUSINESS</p><h1>Coffee supply for<br><em>the work you do.</em></h1><p>Ploomi is the new business-focused coffee brand from Bermito. Created for cafés, bakeries, restaurants, hotels and offices across Kerala, Ploomi offers a place to discuss coffee supply, custom blends and practical brewing support.</p>{btn('Tell us about your business','/contact/')}</section><div class="facts"><div><b>No minimum.</b><span>For wholesale orders</span></div><div><b>All across Kerala.</b><span>Free wholesale delivery</span></div><div><b>Made around you.</b><span>Pricing by quotation</span></div></div><section class="section service-details">{''.join(f'<article id="{s[0]}"><span class="service-number">{s[1]} /</span><div><p class="eyebrow">{s[3]}</p><h2>{s[2]}</h2></div><div><p>{s[4]}</p><ul>{"".join("<li>"+i+"</li>" for i in s[5])}</ul><a class="text-link" href="/contact/?interest={s[3].replace(" ","%20")}">Let’s talk ↗</a></div></article>' for s in services)}</section><section class="section how-section"><p class="eyebrow">A SIMPLE START</p><h2>A clear start<br><em>for your coffee supply.</em></h2>{steps}</section><section class="section faq-section"><div><p class="eyebrow">THE PRACTICAL DETAILS</p><h2>Good to<br><em>know.</em></h2></div>{faqs(faqitems[:4])}</section>{cta()}'''
page('wholesale','Wholesale coffee for businesses in Kerala','Coffee supply, custom blends, training and café guidance by Bermito. No minimum order and free wholesale delivery across Kerala.',wholesale,'wholesale')
about=f'''<section class="page-intro section"><p class="eyebrow">PLOOMI COFFEE / BY BERMITO</p><h1>A roastery’s curiosity.<br><em>A new way to share it.</em></h1><p>Ploomi is a new coffee brand by Bermito, created for the cafés and businesses choosing what to serve every day.</p></section><section class="section story-strip about-story"><div class="story-photo"><img src="/assets/farm.jpg" alt="Coffee drying beds in Sri Lanka, featured in Bermito’s Kothmale coffee story"><span>A CONNECTION FROM ORIGIN TO CUP.</span></div><div><p class="eyebrow">HOW BERMITO BEGAN</p><h2>A small lot.<br><em>A lasting question.</em></h2><p>Bermito began with a small lot of coffee that stayed with us. We wanted to understand what made it taste the way it did, and to explore more coffees like it. That interest became our specialty coffee roastery in Kozhikode, Kerala.</p><p>We explore coffees from India and selected origins around the world. At the roastery, Bermito adjusts heat, airflow and time in small batches, aiming to develop sweetness while keeping each coffee’s individual flavours clear.</p><p>Ploomi is our new B2B chapter: a way to bring that experience to cafés and businesses across Kerala. We’ll begin with the practical details — your menu, equipment, preferred flavours and quantity — and build the conversation from there.</p><a class="text-link" href="https://bermito.com/pages/roastery" target="_blank" rel="noopener">Visit Bermito’s roastery story ↗</a></div></section><section class="section values"><p class="eyebrow">WHAT WE BRING TO THE TABLE</p><div class="steps"><article><span>01 /</span><h3>Origin and<br>processing.</h3><p>A coffee’s growing region and the way its fruit is processed shape the choices we make at the roastery. Bermito shares origin and processing details alongside its coffees.</p></article><article><span>02 /</span><h3>Roasting with<br>intention.</h3><p>Bermito roasts in small batches, adjusting heat, airflow and time for each coffee. The aim is sweetness and clear flavour, with attention to the character of the bean.</p></article><article><span>03 /</span><h3>Coffee beyond<br>the bag.</h3><p>Bermito organises tastings and brewing workshops, and has helped bring Kerala producers and their coffees to the cupping table through Kerala Origins events.</p></article></div></section><section class="section split callout"><div><p class="eyebrow">THE NAME ON THE BAG</p><img class="about-logo" src="/assets/ploomi-stacked.svg" width="1360" height="868" loading="lazy" alt="Ploomi Coffee by Bermito"></div><div><p>Ploomi is made for the decisions a café or business faces: choosing a coffee for the menu, finding the right quantity and helping the team prepare it.</p><p>Our first three blends are concepts as the range takes shape. Their final coffee details and availability are still to be confirmed.</p>{btn('Explore the coffee concepts','/coffees/','outline')}</div></section>{cta()}'''
page('about','Our story — a new chapter by Bermito','Meet Ploomi, the new B2B coffee brand by Bermito Coffee Roasters in Kozhikode, Kerala.',about,'about')
def form(samples=False):
 picks='''<fieldset class="blend-choice"><legend>Choose a direction <span>(select any)</span></legend>'''+''.join(f'<label class="choice"><input type="checkbox" name="sample" value="{b["name"]}" data-blend="{b["id"]}"><span><img src="/assets/{b["art"]}" alt=""><b>{b["name"]}</b><small>Concept direction</small></span></label>' for b in blends)+'''<label class="choice recommend"><input type="checkbox" name="sample" value="Please recommend samples"><span><b>Help me choose ↗</b><small>Recommend a starting point</small></span></label></fieldset>''' if samples else '''<div class="field full"><label for="interest">What can we help with?</label><select id="interest" name="interest"><option>Wholesale coffee</option><option>Custom blend</option><option>Training & brewing support</option><option>Equipment & café guidance</option><option>General enquiry</option><option>Tiramisu Blend</option><option>House Blend</option><option>Christmas Blend</option></select></div>'''
 return f'''<form class="enquiry-form" data-type="{'Sample request' if samples else 'Business enquiry'}">{picks}<div class="form-grid"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required maxlength="100" placeholder="Your name"></div><div class="field"><label for="business">Business name *</label><input id="business" name="business" autocomplete="organization" required maxlength="150" placeholder="Your place, or your next idea"></div><div class="field"><label for="email">Email *</label><input type="email" id="email" name="email" autocomplete="email" required maxlength="150" placeholder="you@example.com"></div><div class="field"><label for="phone">Phone / WhatsApp *</label><input type="tel" id="phone" name="phone" autocomplete="tel" required pattern="[+0-9 ]{{7,20}}" title="Enter a phone number using 7–20 digits, spaces or +." placeholder="+91"></div><div class="field"><label for="city">City / town in Kerala *</label><input id="city" name="city" autocomplete="address-level2" required maxlength="100" placeholder="Where are you based?"></div><div class="field"><label for="type">Your business *</label><select id="type" name="businessType" required><option value="">Choose one</option><option>Café / coffee shop</option><option>Restaurant / bakery</option><option>Hotel / resort</option><option>Office / workplace</option><option>Opening a new café</option><option>Other</option></select></div><div class="field"><label for="stage">Where are you at?</label><select id="stage" name="stage"><option>Already open</option><option>Opening soon</option><option>Still planning</option></select></div><div class="field"><label for="volume">Approximate monthly coffee (kg)</label><input type="number" id="volume" name="volume" min="0" step="0.1" placeholder="Optional — no minimum order"></div><div class="field full"><label for="message">Tell us a little more</label><textarea id="message" name="message" rows="4" maxlength="2000" placeholder="Your menu, brewing setup, preferred coffee, or questions for us…"></textarea></div></div><label class="consent"><input type="checkbox" name="consent" required><span>I agree to share these details with Bermito for this enquiry. <a href="/privacy/">Privacy details</a></span></label><div class="form-actions"><button class="button primary" type="submit" name="channel" value="whatsapp">Continue on WhatsApp ↗</button><button class="button outline" type="submit" name="channel" value="email">Continue by email ↗</button></div><p class="fine">Your details are prepared as a message. Review and send it in WhatsApp or your email app. Nothing is sent until you do.</p><div class="send-status" aria-live="polite" hidden><b>Your enquiry is ready.</b><p>Finish sending it in the app that opens. You can also copy the message and email it to {EMAIL}.</p><button type="button" class="text-link copy-message">Copy enquiry message</button></div></form>'''
